package com.bank.messaging;

import java.util.*;
import java.util.logging.*;

public class MessagingDemo {
    private static final Logger log = Logger.getLogger("MQ");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Topic topic = new Topic("transfers", 3);  // 3 partitions
        Producer producer = new Producer(topic);
        DeadLetterQueue dlq = new DeadLetterQueue();

        // Produce transfer events keyed by account (per-key order preserved)
        producer.send("SAV2001", "msg-1:transfer 50000");
        producer.send("SAV2001", "msg-2:transfer 20000");  // same partition, after msg-1
        producer.send("CUR3001", "msg-3:transfer 10000");
        producer.send("SAV2001", "msg-1:transfer 50000");  // DUPLICATE (redelivery)
        producer.send("SAV2001", "POISON:bad-payload");    // will fail → DLQ

        // Consumer group of 2 shares the 3 partitions
        ConsumerGroup group = new ConsumerGroup("ledger-group", topic, dlq, 2);
        group.consumeAll();

        log.info(() -> "Dead letters: " + dlq.all());
    }
}

