package com.bank.messaging;

import java.util.logging.*;

public class Producer {
    private static final Logger log = Logger.getLogger("MQ");
    private final Topic topic;
    public Producer(Topic topic) { this.topic = topic; }

    // key decides the partition → same key always same partition (ordering)
    public void send(String key, String message) {
        int p = topic.partitionFor(key);
        topic.append(p, message);
        log.fine(() -> "produced to partition " + p + ": " + message);
    }
}
