package com.bank.messaging;

import java.util.*;
import java.util.logging.*;

public class ConsumerGroup {
    private static final Logger log = Logger.getLogger("MQ");
    private final Topic topic;
    private final List<IdempotentConsumer> members = new ArrayList<>();

    public ConsumerGroup(String groupId, Topic topic, DeadLetterQueue dlq, int size) {
        this.topic = topic;
        for (int i = 0; i < size; i++) members.add(new IdempotentConsumer(groupId + "-c" + i, dlq));
        log.info(() -> "group " + groupId + " with " + size + " consumers over "
            + topic.partitionCount() + " partitions");
    }

    // assign partitions to consumers round-robin: each partition to exactly one member
    public void consumeAll() {
        for (int p = 0; p < topic.partitionCount(); p++) {
            IdempotentConsumer owner = members.get(p % members.size());
            String msg;
            while ((msg = topic.partition(p).pollFirst()) != null)
                owner.consume(p, msg);  // in-partition order preserved
        }
    }
}
